// 401 からのメトリクスデータを受け取り、分析対象を抽出
const metrics = $input.first().json;

// 投稿ごとのパフォーマンスデータを抽出
const analysis_period = metrics.period;
const platforms = metrics.platform_breakdown;

// 各媒体の投稿データ
const posts_to_analyze = {
  threads: {
    platform: 'Threads',
    impressions: platforms.threads.impressions || 0,
    clicks: platforms.threads.clicks || 0,
    engagement_rate: platforms.threads.impressions > 0 ? ((platforms.threads.clicks / platforms.threads.impressions) * 100).toFixed(2) : 0
  },
  note: {
    platform: 'note',
    views: platforms.note.views || 0,
    sales: platforms.note.sales || 0,
    conversion_rate: platforms.note.views > 0 ? ((platforms.note.sales / platforms.note.views) * 100).toFixed(2) : 0
  },
  wordpress: {
    platform: 'WordPress',
    pv: platforms.wordpress.pv || 0,
    clicks: platforms.wordpress.clicks || 0,
    ctr: platforms.wordpress.pv > 0 ? ((platforms.wordpress.clicks / platforms.wordpress.pv) * 100).toFixed(2) : 0
  },
  rakuten: {
    platform: '楽天room',
    views: platforms.rakuten.views || 0,
    sales: platforms.rakuten.sales || 0
  },
  amazon: {
    platform: 'Amazon',
    clicks: platforms.amazon.clicks || 0,
    conversions: platforms.amazon.conversions || 0
  }
};

return [{ json: { period: analysis_period, posts_to_analyze } }];

// 高反応投稿と低反応投稿を特定
const data = $input.first().json;
const posts = data.posts_to_analyze;

// エンゲージメント率でランキング
const rankings = [
  { ...posts.threads, rank: 1, score: posts.threads.engagement_rate },
  { ...posts.note, rank: 2, score: posts.note.conversion_rate },
  { ...posts.wordpress, rank: 3, score: posts.wordpress.ctr }
].sort((a, b) => b.score - a.score);

const high_performers = rankings.slice(0, 3);
const low_performers = rankings.slice(3);

return [{ json: {
  period: data.period,
  high_performers,
  low_performers,
  all_posts: posts
} }];

// Claude API を使用して、高反応投稿から共通パターンを抽出
const data = $input.first().json;
const high_perf = data.high_performers;

const prompt = `以下は、最近の投稿の中で反応が最も高かった投稿です。\n\n${JSON.stringify(high_perf, null, 2)}\n\n\nこれらの投稿に共通する要素（テーマ・文体・構成・ターゲット）を分析してください。次の投稿で活かすべき「成功パターン」を 3 つ抽出してください。\n\n出力形式（JSON）:\n[\n  { "pattern": "成功パターン1", "reason": "理由", "example": "具体例" },\n  { "pattern": "成功パターン2", "reason": "理由", "example": "具体例" },\n  { "pattern": "成功パターン3", "reason": "理由", "example": "具体例" }\n]`;

const anthropic_body = {
  model: 'claude-haiku-4-5',
  max_tokens: 1024,
  messages: [{ role: 'user', content: prompt }]
};

return [{ json: { ...data, anthropic_body, prompt } }];

// 低反応投稿の改善案を Claude に生成させる
const data = $input.first().json;
const low_perf = data.low_performers;

const prompt = `以下は、最近の投稿の中で反応が低かった投稿です。

${JSON.stringify(low_perf, null, 2)}


これらの投稿を改善するために、以下を提案してください：
1. タイトル/文頭を改善した場合の新案
2. 文体・トーン・構成の変更提案
3. ターゲットまたはテーマの見直し

出力形式（JSON）:
[
  { "platform": "媒体名", "improvement": "改善内容", "new_title": "新しいタイトル例", "expected_impact": "期待される効果" }
]`;

const anthropic_body = {
  model: 'claude-haiku-4-5',
  max_tokens: 1024,
  messages: [{ role: 'user', content: prompt }]
};

return [{ json: { ...data, improvement_body: anthropic_body } }];

// Claude 応答をパース（成功パターン）
const patterns_result = $('Claude: Extract Success Patterns').first().json;
const improvements_result = $('Claude: Generate Improvements').first().json;
const data = $input.first().json;

let success_patterns = null;
let improvement_suggestions = null;
let patterns_error = null;
let improvements_error = null;

try {
  if (patterns_result?.content && patterns_result.content[0]?.text) {
    const text = patterns_result.content[0].text;
    const match = text.match(/\[[\s\S]*\]/);
    success_patterns = JSON.parse(match ? match[0] : text);
  } else {
    patterns_error = 'patterns_parse_failed';
  }
} catch (e) {
  patterns_error = 'patterns_json_error: ' + e.message;
}

try {
  if (improvements_result?.content && improvements_result.content[0]?.text) {
    const text = improvements_result.content[0].text;
    const match = text.match(/\[[\s\S]*\]/);
    improvement_suggestions = JSON.parse(match ? match[0] : text);
  } else {
    improvements_error = 'improvements_parse_failed';
  }
} catch (e) {
  improvements_error = 'improvements_json_error: ' + e.message;
}

if (patterns_error) success_patterns = [{ pattern: '分析失敗', reason: patterns_error }];
if (improvements_error) improvement_suggestions = [{ platform: '不明', improvement: improvements_error }];

return [{ json: {
  period: data.period,
  success_patterns,
  improvement_suggestions,
  high_performers: data.high_performers,
  low_performers: data.low_performers,
  state: 'READY_FOR_SLACK',
  errors: { patterns: patterns_error, improvements: improvements_error }
} }];

// ライターエージェント呼び出しの準備
// 分析結果を JSON で出力（DEV_RIO_603 へ webhook で渡す準備）
const d = $input.first().json;
return [{ json: { ...d, note: '分析完了。ライターエージェント呼び出し準備完了' } }];
